import pandas as pd
import numpy as np


def _cme_month_expiry(year: int, month: int) -> pd.Timestamp:
    """Last Friday of the month, 15:00 UTC proxy for CME's 4pm London cash settlement."""
    last_day = pd.Timestamp(year=year, month=month, day=1) + pd.offsets.MonthEnd(1)
    offset = (last_day.dayofweek - 4) % 7
    last_fri = last_day - pd.Timedelta(days=int(offset))
    return last_fri.replace(hour=15, minute=0, second=0)


def _monthly_expiries(idx: pd.DatetimeIndex) -> pd.DatetimeIndex:
    if len(idx) == 0:
        return pd.DatetimeIndex([])
    years = range(idx.min().year, idx.max().year + 1)
    out = []
    for y in years:
        for m in range(1, 13):
            ts = _cme_month_expiry(y, m)
            if idx.tz is not None:
                ts = ts.tz_localize(idx.tz)
            out.append(ts)
    return pd.DatetimeIndex(sorted(out))


def signals(df: pd.DataFrame) -> pd.Series:
    idx = df.index
    out = pd.Series(0, index=idx, dtype=int)
    for exp in _monthly_expiries(idx):
        entry_start = exp - pd.Timedelta(hours=72)
        mask = (idx >= entry_start) & (idx < exp)
        window_idx = idx[mask]
        if len(window_idx) == 0:
            continue
        out.loc[window_idx] = 1
    return out.fillna(0).astype(int)
